package com.procuremind.platform.inventory;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.procuremind.platform.common.BusinessException;
import com.procuremind.platform.system.SecurityUtils;
import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.*;

@Service
public class ReceiptService {
    private final JdbcTemplate jdbc;private final ObjectMapper mapper;
    public ReceiptService(JdbcTemplate jdbc,ObjectMapper mapper){this.jdbc=jdbc;this.mapper=mapper;}
    @Transactional public Map<String,Object> receive(String key,Request r){if(key==null||key.isBlank()||key.length()>100)throw new BusinessException(HttpStatus.BAD_REQUEST,"必须提供不超过100字符的Idempotency-Key");Long user=SecurityUtils.currentUser().id();try{jdbc.update("insert into sys_idempotency_record(idempotency_key,user_id,operation,status) values(?,?,?,'PROCESSING')",key,user,"CREATE_RECEIPT");}catch(DuplicateKeyException e){var rows=jdbc.queryForList("select status,response_json from sys_idempotency_record where idempotency_key=? and user_id=? and operation='CREATE_RECEIPT'",key,user);if(!rows.isEmpty()&&"COMPLETED".equals(rows.getFirst().get("status")))try{return mapper.readValue(rows.getFirst().get("response_json").toString(),new TypeReference<>(){});}catch(Exception ex){throw new BusinessException(HttpStatus.CONFLICT,"幂等结果解析失败");}throw new BusinessException(HttpStatus.CONFLICT,"相同请求正在处理中");}
        Map<String,Object> order=jdbc.queryForMap("select status from po_purchase_order where id=? and deleted=0 for update",r.purchaseOrderId());if(!List.of("APPROVED","PARTIALLY_RECEIVED").contains(order.get("status").toString()))throw new BusinessException(HttpStatus.CONFLICT,"仅已审批或部分收货订单允许收货");if(jdbc.queryForObject("select count(*) from md_warehouse where id=? and enabled=1 and deleted=0",Long.class,r.warehouseId())==0)throw new BusinessException(HttpStatus.BAD_REQUEST,"仓库不存在或已停用");if(r.items()==null||r.items().isEmpty())throw new BusinessException(HttpStatus.BAD_REQUEST,"收货明细不能为空");Set<Long> orderItems=new HashSet<>();for(Item item:r.items())if(!orderItems.add(item.orderItemId()))throw new BusinessException(HttpStatus.BAD_REQUEST,"同一订单明细不能重复收货");String no="GRN"+System.currentTimeMillis();jdbc.update("insert into inv_receipt(receipt_no,purchase_order_id,warehouse_id,receiver_id,receipt_date,remark,created_by,updated_by) values(?,?,?,?,?,?,?,?)",no,r.purchaseOrderId(),r.warehouseId(),user,Instant.now(),r.remark(),user,user);Long receiptId=jdbc.queryForObject("select id from inv_receipt where receipt_no=?",Long.class,no);
        for(Item input:r.items()){Map<String,Object> item=jdbc.queryForMap("select i.material_id,i.quantity,i.received_quantity,m.tracking_mode from po_purchase_order_item i join md_material m on m.id=i.material_id where i.id=? and i.purchase_order_id=? for update",input.orderItemId(),r.purchaseOrderId());if(input.quantity()==null||input.quantity().signum()<=0)throw new BusinessException(HttpStatus.BAD_REQUEST,"收货数量必须大于0");BigDecimal remaining=((BigDecimal)item.get("quantity")).subtract((BigDecimal)item.get("received_quantity"));if(input.quantity().compareTo(remaining)>0)throw new BusinessException(HttpStatus.CONFLICT,"收货数量超过订单剩余数量");String mode=item.get("tracking_mode").toString();validateTracking(mode,input);Long materialId=((Number)item.get("material_id")).longValue();String serialJson=json(input.serialNumbers());jdbc.update("insert into inv_receipt_item(receipt_id,order_item_id,material_id,quantity,batch_no,serial_numbers_json,created_by,updated_by) values(?,?,?,?,?,?,?,?)",receiptId,input.orderItemId(),materialId,input.quantity(),input.batchNo(),serialJson,user,user);Long receiptItemId=jdbc.queryForObject("select last_insert_id()",Long.class);if(jdbc.update("update po_purchase_order_item set received_quantity=received_quantity+?,version=version+1,updated_by=? where id=? and received_quantity+?<=quantity",input.quantity(),user,input.orderItemId(),input.quantity())!=1)throw new BusinessException(HttpStatus.CONFLICT,"订单明细已被并发更新，请重试");BigDecimal balance=addBalance(r.warehouseId(),materialId,input.quantity(),user);if("BATCH".equals(mode))jdbc.update("insert into inv_batch(warehouse_id,material_id,batch_no,quantity) values(?,?,?,?) on duplicate key update quantity=quantity+values(quantity)",r.warehouseId(),materialId,input.batchNo(),input.quantity());if("SERIAL".equals(mode))for(String serial:input.serialNumbers())try{jdbc.update("insert into inv_serial(warehouse_id,material_id,serial_no,receipt_item_id) values(?,?,?,?)",r.warehouseId(),materialId,serial,receiptItemId);}catch(DuplicateKeyException e){throw new BusinessException(HttpStatus.CONFLICT,"序列号已存在："+serial);}jdbc.update("insert into inv_ledger(warehouse_id,material_id,business_type,business_id,direction,quantity,balance_after,batch_no,created_by,request_id) values(?,?, 'RECEIPT',?,'IN',?,?,?,?,?)",r.warehouseId(),materialId,receiptId,input.quantity(),balance,input.batchNo(),user,key);}
        Long unfinished=jdbc.queryForObject("select count(*) from po_purchase_order_item where purchase_order_id=? and received_quantity<quantity and deleted=0",Long.class,r.purchaseOrderId());jdbc.update("update po_purchase_order set status=?,updated_by=? where id=?",unfinished==0?"RECEIVED":"PARTIALLY_RECEIVED",user,r.purchaseOrderId());Map<String,Object> response=new LinkedHashMap<>();response.put("id",receiptId);response.put("receiptNo",no);response.put("orderStatus",unfinished==0?"RECEIVED":"PARTIALLY_RECEIVED");jdbc.update("update sys_idempotency_record set status='COMPLETED',response_json=? where idempotency_key=? and user_id=? and operation='CREATE_RECEIPT'",json(response),key,user);return response;}
    private BigDecimal addBalance(Long warehouse,Long material,BigDecimal quantity,Long user){jdbc.update("insert into inv_balance(warehouse_id,material_id,quantity,created_by,updated_by) values(?,?,0,?,?) on duplicate key update id=id",warehouse,material,user,user);for(int i=0;i<3;i++){Map<String,Object> b=jdbc.queryForMap("select id,quantity,version from inv_balance where warehouse_id=? and material_id=? and deleted=0",warehouse,material);BigDecimal next=((BigDecimal)b.get("quantity")).add(quantity);if(jdbc.update("update inv_balance set quantity=?,version=version+1,updated_by=? where id=? and version=?",next,user,b.get("id"),b.get("version"))==1)return next;}throw new BusinessException(HttpStatus.CONFLICT,"库存被并发更新，请重试");}
    private void validateTracking(String mode,Item item){if("BATCH".equals(mode)&&(item.batchNo()==null||item.batchNo().isBlank()))throw new BusinessException(HttpStatus.BAD_REQUEST,"批次物资必须填写批次号");if("SERIAL".equals(mode)){if(item.quantity().stripTrailingZeros().scale()>0)throw new BusinessException(HttpStatus.BAD_REQUEST,"序列号物资数量必须为整数");if(item.serialNumbers()==null||item.serialNumbers().size()!=item.quantity().intValueExact())throw new BusinessException(HttpStatus.BAD_REQUEST,"序列号数量必须与收货数量一致");if(item.serialNumbers().stream().anyMatch(v->v==null||v.isBlank()))throw new BusinessException(HttpStatus.BAD_REQUEST,"序列号不能为空");if(new HashSet<>(item.serialNumbers()).size()!=item.serialNumbers().size())throw new BusinessException(HttpStatus.BAD_REQUEST,"序列号不能重复");}}
    private String json(Object value){try{return value==null?null:mapper.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
    public record Request(@NotNull Long purchaseOrderId,@NotNull Long warehouseId,@Size(max=500) String remark,@NotEmpty @Size(max=100) List<@Valid Item> items){}
    public record Item(@NotNull Long orderItemId,@NotNull @DecimalMin(value="0",inclusive=false) BigDecimal quantity,@Size(max=100) String batchNo,List<@Size(max=200) String> serialNumbers){}
}
